'use strict';

// #450 pilot, phase 3 — does the live #449 trigger signal (pipeline-disposition.js's
// `reaction` field) actually resolve to the right generated image? Phase 1
// (test-disposition-reaction.js) confirmed the model self-reports reliably in
// the abstract; this confirms the concrete naming-convention mapping
// (`<id>-<reaction>.png`) lands on a real file for the pilot cohort
// (crowley/yeats/teresa), using the actual candidates generated by
// scripts/pilot-reaction-portraits.js. Not full #452 client wiring — just the
// resolver logic #452 will need, checked against real live model output.
//
// Run with: node scripts/test-reaction-portrait-trigger.js

require('dotenv').config();
const fs = require('fs');
const path = require('path');
const Anthropic = require('@anthropic-ai/sdk');
const {
  buildDispositionSystemPrompt,
  buildDispositionUserMessage,
  callDispositionUpdate,
} = require('../src/pipeline-disposition');

const ROOT = path.join(__dirname, '..');
const ROSTER = JSON.parse(fs.readFileSync(path.join(ROOT, 'prompts/members/roster.json'), 'utf8'));
const MODEL = process.env.MODEL || 'claude-sonnet-5';
const CANDIDATES_DIR = path.join(ROOT, 'public', 'portraits', 'candidates');
const PORTRAITS_DIR = path.join(ROOT, 'public', 'portraits');

const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });

function member(id) {
  return ROSTER.find(x => x.id === id);
}

// Same naming convention #450 settled on: `<id>-<reaction>.png`. "none"
// falls back to the existing baseline `<id>.png` — there's no "none" image to
// generate, the default portrait already covers it.
function resolvePortraitPath(memberId, reaction) {
  if (reaction === 'none') return path.join(PORTRAITS_DIR, `${memberId}.png`);
  // Candidates aren't promoted yet (pending human review) — check candidates/
  // first, falling back to the canonical path once promoted.
  const candidate = path.join(CANDIDATES_DIR, `${memberId}-${reaction}.png`);
  if (fs.existsSync(candidate)) return candidate;
  return path.join(PORTRAITS_DIR, `${memberId}-${reaction}.png`);
}

// Real turns, written for the pilot cohort specifically — same spirit as
// test-disposition-reaction.js's cases, restricted to the 3 members actually
// piloted so this checks the real generated files, not hypothetical ones.
const CASES = [
  {
    memberId: 'crowley',
    presentIds: ['yeats', 'blavatsky'],
    roundSoFarText: `Yeats\nCrowley, I confess — reading it back tonight, your gloss on the Abramelin working is the clearest thing anyone in this room has said about it in years.`,
    turnText: `Well. Coming from you, Willie, that's nearly worth the eleven years it took the Order to catch up with me. I could kiss you for it — don't test whether I mean that literally.`,
  },
  {
    memberId: 'yeats',
    presentIds: ['crowley', 'pixie'],
    roundSoFarText: `Coleman-Smith\nBut does the card's meaning live in the image, or in what the reader brings to it?`,
    turnText: `I don't know, Pixie, and I find I don't want to answer too quickly. If the meaning is only what's brought to it, the image is just a mirror — but I've felt something look back that wasn't my own face. I'd like to turn that over a while longer before I say more.`,
  },
  {
    memberId: 'teresa',
    presentIds: ['eckhart', 'julian'],
    roundSoFarText: `Eckhart\nWith respect, Teresa — perhaps what you call the Interior Castle is simply the imagination dressed up in theological language.`,
    turnText: `No. I will not sit quietly while thirty years of prayer, examined and re-examined against my confessors' own doubt, is waved away as imagination dressed up. You did not carry what I carried to write it, Meister, and I ask you not to speak of it as though you did.`,
  },
];

const EXPECTED = { crowley: 'happy', yeats: 'thinking', teresa: 'angry' };

async function runCase(c) {
  const m = member(c.memberId);
  const presentMembers = [m, ...c.presentIds.map(member)];
  const system = buildDispositionSystemPrompt({
    member: m,
    priorDisposition: null,
    presentMembers,
    priorResidue: null,
    libraryList: null,
  });
  const userMessage = buildDispositionUserMessage({
    roundSoFarText: c.roundSoFarText,
    turnText: c.turnText,
    member: m,
  });

  const result = await callDispositionUpdate({
    client,
    model: MODEL,
    system,
    userMessage,
    presentIds: c.presentIds,
    libraryIds: [],
  });

  const resolvedPath = resolvePortraitPath(c.memberId, result.reaction);
  const fileExists = fs.existsSync(resolvedPath);
  const expected = EXPECTED[c.memberId];
  const matchedExpected = result.reaction === expected;

  console.log(`\n--- ${m.name} ---`);
  console.log(`reflection: ${result.text}`);
  console.log(
    `reaction: ${result.reaction} (expected ${expected}, ${matchedExpected ? 'match' : 'differs — real model variance'})`
  );
  console.log(`resolved portrait path: ${path.relative(ROOT, resolvedPath)}`);
  console.log(
    fileExists
      ? '✅ file exists on disk — trigger correctly resolved to a real generated image'
      : '❌ resolved path does not exist'
  );

  return { memberId: c.memberId, reaction: result.reaction, resolvedPath, fileExists };
}

async function main() {
  if (!process.env.ANTHROPIC_API_KEY) {
    console.error('ANTHROPIC_API_KEY not set — cannot run live disposition calls.');
    process.exit(1);
  }

  const results = [];
  for (const c of CASES) {
    results.push(await runCase(c));
  }

  console.log('\n=== SUMMARY ===');
  const allResolved = results.every(r => r.fileExists);
  console.log(
    allResolved
      ? '✅ every live reaction tag resolved to a real, on-disk generated image — the trigger signal works end to end for the pilot cohort.'
      : '❌ at least one reaction tag did not resolve to an existing file.'
  );
  for (const r of results) {
    console.log(
      `  ${r.memberId}: reaction="${r.reaction}" -> ${path.relative(ROOT, r.resolvedPath)} (${r.fileExists ? 'exists' : 'MISSING'})`
    );
  }

  process.exit(allResolved ? 0 : 1);
}

main().catch(err => {
  console.error('Script error:', err);
  process.exit(1);
});
